import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"光学现象","description":"","frontmatter":{"title":"光学现象"},"headers":[],"relativePath":"zh/classification/optical-phenomena/intro.md","filePath":"zh/classification/optical-phenomena/intro.md","lastUpdated":1790876393000}'),l={name:"zh/classification/optical-phenomena/intro.md"};function o(n,t,h,i,s,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="光学现象" tabindex="-1">光学现象 <a class="header-anchor" href="#光学现象" aria-label="Permalink to &quot;光学现象&quot;">​</a></h1><p>除了基础颜色，天然宝石可通过内部结构展示多种独特的光学效应。以下七种是最具代表性、也最容易在鉴定中观察到的现象：</p><h2 id="先学会观察" tabindex="-1">先学会观察 <a class="header-anchor" href="#先学会观察" aria-label="Permalink to &quot;先学会观察&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>建议观察方式</th><th>优先寻找的结构线索</th></tr></thead><tbody><tr><td>星光效应</td><td>单点光源直射并缓慢转动弧面宝石</td><td>定向针状或管状包裹体</td></tr><tr><td>猫眼效应</td><td>移动光源或转动弧面宝石，追踪亮带</td><td>平行纤维、管状包裹体或通道</td></tr><tr><td>变色效应</td><td>分别在日光与暖色光源下比较</td><td>不同光源光谱与选择性吸收</td></tr><tr><td>变彩（游彩）</td><td>缓慢倾斜，观察色斑移动与分布</td><td>有序二氧化硅微球结构</td></tr><tr><td>月光效应</td><td>转动弧面宝石，观察漂浮光晕</td><td>长石内部交替层状结构</td></tr><tr><td>拉长晕彩</td><td>改变角度，观察金属感色彩闪烁</td><td>长石成分层状结构</td></tr><tr><td>砂金效应</td><td>倾斜宝石，让片状包裹体依次反光</td><td>定向金属片状包裹体</td></tr></tbody></table><h2 id="七种主要现象" tabindex="-1">七种主要现象 <a class="header-anchor" href="#七种主要现象" aria-label="Permalink to &quot;七种主要现象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>一句话概述</th></tr></thead><tbody><tr><td><a href="./asterism.html">星光效应</a></td><td>平行针状包裹体反射光线形成星芒</td></tr><tr><td><a href="./chatoyancy.html">猫眼效应</a></td><td>平行纤维或管状包裹体形成一道亮带</td></tr><tr><td><a href="./color-change.html">变色效应</a></td><td>不同光源下呈现明显不同颜色</td></tr><tr><td><a href="./play-of-color.html">变彩（游彩）</a></td><td>角度变化时出现跳动的光谱色斑</td></tr><tr><td><a href="./adularescence.html">月光效应</a></td><td>内部层状结构产生柔和漂浮的蓝色光晕</td></tr><tr><td><a href="./labradorescence.html">拉长晕彩</a></td><td>内部层状结构产生强烈金属光泽的彩色闪烁</td></tr><tr><td><a href="./aventurescence.html">砂金效应</a></td><td>金属片状包裹体在宝石内部闪烁</td></tr></tbody></table><p>观察到一个现象，只能说明宝石呈现了某种光学表现，不能单独作为最终鉴定结论。光源、切磨形状、观察角度和内部包裹体都会影响结果。</p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA：现象宝石指南</a><span>光学现象的观察方式与宝石学语境</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA：现象弧面宝石的光学效应</a><span>弧面切割、光源、角度与光学表现</span><small>打开来源 ↗</small></li></ul></aside><p><em>参见<a href="./../intro.html">分类总览</a>了解矿物学分类框架。</em></p>',9)])])}const f=e(l,[["render",o]]);export{p as __pageData,f as default};
